begin;
select no_plan();
select tests.setup_basic();
insert into public.exercises(id,name,muscle_group) values('e0000000-0000-0000-0000-000000000001','Press detallado','Pecho'),('e0000000-0000-0000-0000-000000000002','Alternativa detallada','Pecho');
insert into public.programs(id,coach_id,name,weeks_count) values('a1000000-0000-0000-0000-000000000001',tests.coach_id(),'Detalle',2);
insert into public.program_sessions(id,program_id,week_number,label) values('a2000000-0000-0000-0000-000000000001','a1000000-0000-0000-0000-000000000001',1,'A');
insert into public.session_exercises(id,program_session_id,exercise_id,position,sets,reps_min,reps_max,target_weight_kg,prescription_sets) values('a3000000-0000-0000-0000-000000000001','a2000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001',0,2,6,12,null,'[{"repsMin":6,"repsMax":8,"targetWeightKg":75},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]');
insert into public.session_exercise_alternatives(id,session_exercise_id,exercise_id,position,sets,reps_min,reps_max,target_weight_kg,prescription_sets) values('a4000000-0000-0000-0000-000000000001','a3000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000002',0,2,6,12,null,'[{"repsMin":6,"repsMax":8,"targetWeightKg":20},{"repsMin":10,"repsMax":12,"targetWeightKg":15}]');
select col_type_is('public','session_exercises','prescription_sets','jsonb','detalle JSONB en rutina');
select col_is_null('public','session_exercises','prescription_sets','extensión nullable');
select col_type_is('public','session_exercise_alternatives','prescription_sets','jsonb','alternativa con detalle');
select tests.authenticate_as(tests.coach_id());
select throws_ok($$update public.session_exercises set prescription_sets='[]'$$,'23514',null,'no admite lista vacía');
select throws_ok($$update public.session_exercises set prescription_sets='null'$$,'23514',null,'JSON null no es lista');
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":6,"repsMax":8,"targetWeightKg":75}]'$$,'23514',null,'cantidad coincide con sets');
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":6,"repsMax":8,"targetWeightKg":501},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]'$$,'23514',null,'peso máximo');
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":6,"repsMax":8,"targetWeightKg":1.001},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]'$$,'23514',null,'precisión SQL');
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":6.5,"repsMax":8,"targetWeightKg":75},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]'$$,'23514',null,'reps enteras');
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":9,"repsMax":8,"targetWeightKg":75},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]'$$,'23514',null,'rango ordenado');
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":6,"repsMax":8,"targetWeightKg":75,"restSeconds":90},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]'$$,'23514',null,'sin campos fuera del contrato');
select throws_ok($$update public.session_exercises set target_weight_kg=75$$,'23514',null,'resumen no sustituye pesos diferentes');
select throws_ok($$update public.session_exercise_alternatives set prescription_sets='[]'$$,'23514',null,'mismos límites en alternativa');
select lives_ok($$insert into public.session_exercises(program_session_id,exercise_id,position,sets,reps_min,reps_max) values('a2000000-0000-0000-0000-000000000001','e0000000-0000-0000-0000-000000000001',1,3,8,12)$$,'prescripción uniforme sigue válida');
select is((select count(*)::int from public.session_exercises where prescription_sets is null),1,'no inventa detalle para datos uniformes');
reset role;
update public.programs set student_id=tests.student_a_id(),start_date=tests.current_monday(),ends_on=tests.current_monday()+13;
select tests.authenticate_as(tests.coach_id());
select throws_ok($$update public.session_exercises set prescription_sets='[{"repsMin":6,"repsMax":8,"targetWeightKg":60},{"repsMin":10,"repsMax":12,"targetWeightKg":70}]' where id='a3000000-0000-0000-0000-000000000001'$$,'55000',null,'semana vigente protege detalle en SQL directo');
reset role;
select tests.authenticate_as(tests.student_a_id());
update public.session_exercises set prescription_sets=null;
update public.session_exercise_alternatives set prescription_sets=null;
select is((select count(*)::int from public.session_exercises where prescription_sets is not null),1,'alumno no altera detalle');
select is((select count(*)::int from public.session_exercise_alternatives where prescription_sets is not null),1,'alumno no altera alternativa');
reset role;
select tests.authenticate_as_anon();
select throws_ok($$select prescription_sets from public.session_exercises$$,'42501',null,'anónimo no lee detalle');
reset role;
select * from finish();
rollback;
